#include <WiFi.h>
#include <WebServer.h>

// true  = الـ ESP32 يعمل شبكة واي فاي خاصة بيه (الأسهل، العنوان دايمًا 192.168.4.1)
// false = يتصل بالراوتر بتاعك
const bool AP_MODE = true;

const char* SSID = "ESP32-Robot";     // اسم الشبكة (في AP) أو شبكة البيت (في STA)
const char* PASS = "12345678";        // لازم 8 حروف على الأقل

const int LED_PIN = 2;                // الـ LED المدمج
WebServer server(80);

const char PAGE[] PROGMEM = R"rawliteral(
<!DOCTYPE html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
 body{font-family:sans-serif;text-align:center;margin-top:30px}
 button{font-size:22px;padding:18px 28px;margin:8px;border-radius:12px}
</style></head><body>
<h2>ESP32 Control</h2>
<button onclick="send('led/on')">LED ON</button>
<button onclick="send('led/off')">LED OFF</button><br>
<button onclick="send('forward')">⬆️</button><br>
<button onclick="send('left')">⬅️</button>
<button onclick="send('stop')">⏹</button>
<button onclick="send('right')">➡️</button><br>
<button onclick="send('backward')">⬇️</button>
<p id="s"></p>
<script>
function send(c){
  fetch('/'+c).then(r=>r.text()).then(t=>document.getElementById('s').innerText=t);
}
</script></body></html>
)rawliteral";

void reply(const char* msg) { server.send(200, "text/plain", msg); }

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);

  if (AP_MODE) {
    WiFi.softAP(SSID, PASS);
    Serial.print("AP IP: ");
    Serial.println(WiFi.softAPIP());
  } else {
    WiFi.begin(SSID, PASS);
    while (WiFi.status() != WL_CONNECTED) { delay(500); Serial.print("."); }
    Serial.print("\nIP: ");
    Serial.println(WiFi.localIP());
  }

  server.on("/", []() { server.send_P(200, "text/html", PAGE); });
  server.on("/led/on",  []() { digitalWrite(LED_PIN, HIGH); reply("LED on"); });
  server.on("/led/off", []() { digitalWrite(LED_PIN, LOW);  reply("LED off"); });

  // هنا هتحط أكواد الموتورات بعدين
  server.on("/forward",  []() { reply("forward"); });
  server.on("/backward", []() { reply("backward"); });
  server.on("/left",     []() { reply("left"); });
  server.on("/right",    []() { reply("right"); });
  server.on("/stop",     []() { reply("stop"); });

  server.begin();
}

void loop() {
  server.handleClient();
}
